components.css:
.ds-btn-primary {
  width: 100%;
  height: 44px;
  border: 0;
  border-radius: 10px;
  background: #ff9f0a;
  color: #1c1c1e;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif;
  font-size: 14px;
  font-weight: 590;
  cursor: pointer;
  transition: background 140ms ease, transform 80ms ease;
}
.ds-btn-primary:hover { background: #ffb340; }
.ds-btn-primary:active { transform: scale(0.99); }
.ds-btn-primary:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }
.ds-btn-primary:disabled { background: rgba(255, 159, 10, 0.35); color: rgba(28, 28, 30, 0.55); cursor: default; transform: none; }

.ds-input-ip {
  width: 100%;
  height: 44px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.35);
  color: #f5f5f7;
  caret-color: #ff9f0a;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif;
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  box-sizing: border-box;
}
.ds-input-ip::placeholder { color: #8e8e93; }
.ds-input-ip:focus { border-color: #ff9f0a; outline: none; box-shadow: 0 0 0 3px rgba(255, 159, 10, 0.22); }

.ds-status { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; background: rgba(255,255,255,0.06); color: #98989d; }
.ds-status[data-state="connecting"], .ds-status[data-state="warning"] { color: #ffd60a; }
.ds-status[data-state="connected"] { color: #30d158; }
.ds-status[data-state="error"] { color: #ff453a; }
.ds-status-icon { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.ds-status-slash { opacity: 0; }
.ds-status[data-state="idle"] .ds-status-slash, .ds-status[data-state="error"] .ds-status-slash { opacity: 1; }

.ds-connect-card {
  width: min(460px, 100%);
  padding: 26px 26px 22px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 22px;
  background: rgba(44, 44, 46, 0.72);
  backdrop-filter: blur(30px) saturate(160%);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
  color: #f5f5f7;
  text-align: center;
  box-sizing: border-box;
}
.ds-connect-title { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif; font-size: 22px; font-weight: 590; letter-spacing: -0.01em; }

.ds-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-width: 120px;
  height: 40px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
  color: #f5f5f7;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif;
  font-size: 12px;
  cursor: pointer;
  transition: background 140ms ease;
}
.ds-pill:hover { background: rgba(255, 255, 255, 0.1); }
.ds-pill:active { background: rgba(255, 255, 255, 0.14); }
.ds-pill:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }
.ds-pill-icon { flex: none; width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; color: #98989d; }

.ds-pill-power {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: 100%;
  height: 40px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
  color: #f5f5f7;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif;
  font-size: 12px;
  cursor: pointer;
  transition: background 140ms ease, color 140ms ease;
}
.ds-pill-power:hover { background: rgba(255, 255, 255, 0.1); }
.ds-pill-power:active { background: rgba(255, 69, 58, 0.16); color: #ffb3b0; }
.ds-pill-power:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }
.ds-pill-power-icon { flex: none; width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; color: #98989d; }
.ds-pill-power:active .ds-pill-power-icon { color: #ffb3b0; }

.ds-clickpad { position: relative; width: 184px; height: 184px; margin: 6px auto 10px; border-radius: 50%; }
.ds-clickpad-ring { position: absolute; inset: 0; border-radius: 50%; background: radial-gradient(circle at 50% 30%, #3a3a3c 0%, #2c2c2e 55%, #242426 100%); box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), inset 0 -8px 18px rgba(0,0,0,0.35), 0 12px 28px rgba(0,0,0,0.4); }
.ds-pad { position: absolute; display: grid; place-items: center; width: 44px; height: 44px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: #d1d1d6; cursor: pointer; transition: background 140ms ease; }
.ds-pad:hover { background: rgba(255,255,255,0.07); }
.ds-pad:active { background: rgba(255,255,255,0.12); }
.ds-pad:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }
.ds-pad-icon { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.ds-pad-up { top: 8px; left: 70px; }
.ds-pad-right { top: 70px; right: 8px; }
.ds-pad-down { bottom: 8px; left: 70px; }
.ds-pad-left { top: 70px; left: 8px; }
.ds-pad-ok { top: 60px; left: 60px; width: 64px; height: 64px; border: 1px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.1); color: #f5f5f7; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif; font-size: 13px; font-weight: 590; }
.ds-pad-ok:hover { background: rgba(255,255,255,0.15); }
.ds-pad-ok:active { background: rgba(255,255,255,0.2); }

.ds-segmented { display: inline-flex; gap: 2px; padding: 2px; border-radius: 10px; background: rgba(255,255,255,0.06); }
.ds-segment { display: grid; place-items: center; width: 30px; height: 24px; padding: 0; border: 0; border-radius: 8px; background: transparent; color: #98989d; cursor: pointer; transition: background 140ms ease, color 140ms ease; }
.ds-segment:hover { color: #f5f5f7; }
.ds-segment-active { background: rgba(255,255,255,0.14); color: #f5f5f7; }
.ds-segment-icon { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.ds-segment:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }

.ds-icon-btn { display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 8px; background: transparent; color: #98989d; cursor: pointer; transition: background 140ms ease, color 140ms ease; }
.ds-icon-btn:hover { background: rgba(255,255,255,0.08); color: #f5f5f7; }
.ds-icon-btn[aria-pressed="true"] { background: rgba(255,159,10,0.16); color: #ff9f0a; }
.ds-icon-btn:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }
.ds-icon { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }

.ds-stop { display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 8px; background: transparent; color: #98989d; cursor: pointer; transition: background 140ms ease, color 140ms ease; }
.ds-stop:disabled { opacity: 0.35; cursor: default; }
.ds-stop:not(:disabled) { color: #ff453a; }
.ds-stop-icon { width: 16px; height: 16px; }
.ds-stop:not(:disabled) .ds-stop-icon { width: 18px; height: 18px; }
.ds-stop:not(:disabled):hover { background: rgba(255,69,58,0.14); }
.ds-stop:not(:disabled):active { background: rgba(255,69,58,0.2); }
.ds-stop:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }

.ds-settings { width: 560px; padding: 22px; border: 1px solid rgba(255,255,255,.1); border-radius: 22px; background: rgba(44,44,46,.72); backdrop-filter: blur(30px) saturate(160%); box-shadow: 0 28px 70px rgba(0,0,0,.6); color: #f5f5f7; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif; }
.ds-settings-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.ds-settings-head h2 { margin: 0; font-size: 22px; font-weight: 590; letter-spacing: -.01em; }
.ds-close { width: 30px; height: 30px; border: 0; border-radius: 8px; background: transparent; color: #98989d; cursor: pointer; }
.ds-group { padding: 14px 0; border-top: 1px solid rgba(255,255,255,.1); }
.ds-group h3 { margin: 0 0 8px; color: #98989d; font-size: 12px; font-weight: 590; letter-spacing: .04em; text-transform: uppercase; }
.ds-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 42px; font-size: 13px; }
.ds-segmented { display: inline-flex; gap: 2px; padding: 2px; border-radius: 10px; background: rgba(255,255,255,.06); }
.ds-segment { height: 24px; padding: 0 10px; border: 0; border-radius: 8px; background: transparent; color: #98989d; cursor: pointer; font-size: 12px; }
.ds-segment-active { background: rgba(255,255,255,.14); color: #f5f5f7; }

.ds-switch { width: 44px; height: 26px; padding: 2px; border: 0; border-radius: 999px; background: rgba(255,255,255,.14); cursor: pointer; transition: background 160ms ease; }
.ds-switch[aria-checked="true"] { background: #ff9f0a; }
.ds-knob { display: block; width: 22px; height: 22px; border-radius: 50%; background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.35); transition: transform 180ms cubic-bezier(.2,.8,.2,1); }
.ds-switch[aria-checked="true"] .ds-knob { transform: translateX(18px); }
.ds-switch:focus-visible { outline: 2px solid #ff9f0a; outline-offset: 2px; }

.ds-confirm { position: fixed; right: 26px; bottom: 26px; width: 252px; padding: 12px; border: 1px solid rgba(255,255,255,.1); border-radius: 12px; background: rgba(28,28,30,.96); box-shadow: 0 18px 40px rgba(0,0,0,.5); color: #f5f5f7; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable Text", "Microsoft YaHei UI", sans-serif; font-size: 12px; display: flex; flex-direction: column; gap: 10px; }
.ds-confirm-actions { display: flex; justify-content: flex-end; gap: 8px; }
.ds-confirm button { height: 30px; padding: 0 12px; border: 0; border-radius: 8px; font-size: 12px; cursor: pointer; }
.ds-confirm-cancel { background: rgba(255,255,255,.08); color: #f5f5f7; }
.ds-confirm-off { background: rgba(255,69,58,.18); color: #ffb3b0; }
